[Better Approach 2] Using Bottom-Up DP (Tabulation) -  O(n^3) Time and O(n^2) SpaceThe approach is similar to the previous one; just instead of breaking down the problem recursively, we iteratively build up the solution by calculating in bottom-up manner. Here, we can use two 2D array dp[][] and isPalin[][], for storing the computed result. dp[i][j] stores the minimum cuts for palindrome partitioning of the substring s[i ... j]isPalin[i][j] tells us whether substring s[i ... j] is a palindromic string or not.We starts with smaller substrings and gradually builds up to the result for entire string. 
            C++

    // C++ Solution for Palindrome Partitioning Problem
// using Bottom Up Dynamic Programming
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

// Function to find the minimum number of cuts 
// needed to partition a string such that 
// every part is a palindrome
int palPartition(string& s) {
    int n = s.length();

    // dp[i][j] = Minimum number of cuts needed for
    // palindrome partitioning of substring s[i..j]
    int dp[n][n];

    // isPalin[i][j] = true if substring s[i..j] 
  	// is palindrome,else false
    bool isPalin[n][n];

    // Every substring of length 1 is a palindrome
    for (int i = 0; i < n; i++) {
        isPalin[i][i] = true;
        dp[i][i] = 0;
    }

    for (int len = 2; len <= n; len++) {

        // Build solution for all substrings s[i ... j] 
      	// of length len
        for (int i = 0, j = i + len - 1; j < n ; i++, j++) {

            // If len is 2, then we just need to
            // compare two characters. 
            if (len == 2)
                isPalin[i][j] = (s[i] == s[j]);

          	// Else need to check two corner characters
            // and value of isPalin[i+1][j-1]
            else
                isPalin[i][j] = (s[i] == s[j]) && 
              						isPalin[i + 1][j - 1];

            // IF s[i..j] is palindrome, then dp[i][j] is 0
            if (isPalin[i][j] == true)
                dp[i][j] = 0;
            else {

            // Make a cut at every possible location starting 
          	// from i to j, and get the minimum cost cut.
                dp[i][j] = INT_MAX;
                for (int k = i; k <= j - 1; k++)
                    dp[i][j] = min(dp[i][j], 1 + 
                                   dp[i][k] + dp[k + 1][j]);
            }
        }
    }

    // Return the min cut value for
    // complete string. i.e., s[0..n-1]
    return dp[0][n - 1];
}

int main() {
    string s = "geek";

    cout << palPartition(s) << endl;
    return 0;
}


